# Initially generated by GitHub Copilot.
from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Sequence

from repo_util.common import (
    local_date_from_git_iso8601,
    read_json,
    run_cmd,
    today_local_date,
)

# Workspace folders that are NOT a plain `bdenckla/<folder name>` GitHub repo, and
# so cannot be re-cloned by guessing a URL from the name. Keep this in step with the
# workspace files; a folder absent from here gets the guessed URL, which is right
# for every ordinary repo.
#
# Gist-ArtScroll is a GIST, not a first-class repo -- which is why `gh repo view
# bdenckla/ArtScroll` 404s (as does the REST endpoint, the one that DOES follow
# rename redirects), and so why a missing folder reads as a dead workspace entry
# rather than a merely un-cloned one. Its real name is the hash below; the folder
# name is one a human chose at clone time. document-index's README links the same
# gist, as a review.
#
# THE "Gist-" PREFIX IS DELIBERATE, and marks exactly the distinction this dict
# exists for: a folder so named cannot be re-cloned by guessing
# bdenckla/<folder name>. Ben's decision, 2026-08-31. The folder was briefly
# renamed to plain ArtScroll that day, to match what this workspace file then
# said, before the reversal settled that the workspace file should follow the
# prefix rather than the other way about. Gist-Hebrew-World is the other gist on
# this naming convention, and it is in no workspace file, so it needs no entry
# here. It DID have a folder under GitRepos until 2026-08-31, when its clone was
# removed: its content had moved into this repo as
# py/author_misc/review_of_hebrew_worlds_phonetic_bible.py, leaving the gist
# itself a stub pointing at the rendered page. Its clone URL is recorded in
# in/repo_maintenance_policy.json under gitrepos_setup_rule's gists key, which
# is now the only record on this machine that the gist exists.
#
# A comment like this cannot live in the .code-workspace file itself, which would
# be the obvious home for it: VS Code tolerates JSONC, but `common.read_json` is a
# plain `json.load`, so a comment there would break the very tooling that reads it.
_NON_REPO_WORKSPACE_FOLDERS = {
    "Gist-ArtScroll": (
        "https://gist.github.com/bdenckla/f04699f2a9c4eccd3220751fdb233722.git",
        "gist: A Review of the ArtScroll Transliterated Linear Siddur (Ashkenaz)",
    ),
}


def _how_to_obtain(folder_name: str) -> str:
    """The clone command that would fix a missing workspace folder.

    A bare "not found" is a dead end for exactly the folders that are hardest to
    restore, so the message carries its own fix -- the same principle as
    ``mb_cmn.paths.require_sibling`` one directory away, which names both
    overrides that would point this repo at a missing sibling.
    """
    known = _NON_REPO_WORKSPACE_FOLDERS.get(folder_name)
    if known is not None:
        url, note = known
        return f"git clone {url} {folder_name}\n  ({note})"
    return f"git clone https://github.com/bdenckla/{folder_name}.git {folder_name}"


@dataclass(frozen=True)
class RepoInfo:
    path: Path
    head_commit: str | None
    head_committer_iso: str | None

    @property
    def name(self) -> str:
        return self.path.name


def _resolve_repo_path(folder_path: str, workspace_dir: Path, repos_root: Path) -> Path:
    candidate = Path(folder_path)
    if candidate.is_absolute():
        return candidate.resolve()

    workspace_relative = (workspace_dir / folder_path).resolve()
    if workspace_relative.exists():
        return workspace_relative

    repos_root_relative = (repos_root / folder_path).resolve()
    if repos_root_relative.exists():
        return repos_root_relative

    return workspace_relative


def load_workspace_repo_dirs(workspace_file: Path, repos_root: Path) -> list[Path]:
    workspace = read_json(workspace_file)
    workspace_dir = workspace_file.parent
    repo_dirs: list[Path] = []

    for folder in workspace["folders"]:
        repo_dir = _resolve_repo_path(folder["path"], workspace_dir, repos_root)
        if not repo_dir.is_dir():
            raise FileNotFoundError(
                f"Workspace folder not found: {repo_dir}\n"
                f"Listed in {workspace_file}. To restore it:\n"
                f"  {_how_to_obtain(repo_dir.name)}"
            )
        repo_dirs.append(repo_dir)

    return repo_dirs


def _select_explicit_repos(
    repo_dirs: Sequence[Path],
    *,
    repos: Sequence[str] | None,
    workspace_dir: Path,
    repos_root: Path,
) -> list[Path]:
    if not repos:
        return list(repo_dirs)

    selected: list[Path] = []
    for token in repos:
        token_lc = token.casefold()
        token_as_path = Path(token)
        token_abs = token_as_path.resolve()
        token_workspace = (workspace_dir / token).resolve()
        token_root = (repos_root / token).resolve()

        match = None
        for repo_dir in repo_dirs:
            if repo_dir.name.casefold() == token_lc:
                match = repo_dir
                break
            if str(repo_dir).casefold() == str(token_abs).casefold():
                match = repo_dir
                break
            if str(repo_dir).casefold() == str(token_workspace).casefold():
                match = repo_dir
                break
            if str(repo_dir).casefold() == str(token_root).casefold():
                match = repo_dir
                break

        if match is None:
            raise ValueError(
                f"Requested repo was not found in workspace folders: {token}"
            )
        if match not in selected:
            selected.append(match)

    return selected


def _is_git_repo(repo_dir: Path) -> bool:
    result = run_cmd(["git", "-C", str(repo_dir), "rev-parse", "--is-inside-work-tree"])
    return result.returncode == 0 and result.stdout.strip() == "true"


def _get_head_info(repo_dir: Path) -> tuple[str | None, str | None]:
    result = run_cmd(
        ["git", "-C", str(repo_dir), "log", "-1", "--pretty=format:%H|%cI"]
    )
    text = result.stdout.strip()
    if result.returncode != 0 or "|" not in text:
        return None, None
    commit_sha, committer_iso = text.split("|", 1)
    return commit_sha, committer_iso


def select_repo_infos(
    workspace_file: Path,
    *,
    repos_root: Path,
    repos: Sequence[str] | None,
    today_only: bool,
) -> list[RepoInfo]:
    workspace_file = workspace_file.resolve()
    workspace_dir = workspace_file.parent
    repo_dirs = load_workspace_repo_dirs(workspace_file, repos_root)
    repo_dirs = _select_explicit_repos(
        repo_dirs,
        repos=repos,
        workspace_dir=workspace_dir,
        repos_root=repos_root,
    )

    selected: list[RepoInfo] = []
    today = today_local_date()

    for repo_dir in repo_dirs:
        if not _is_git_repo(repo_dir):
            continue

        head_commit, head_committer_iso = _get_head_info(repo_dir)
        if today_only:
            if head_committer_iso is None:
                continue
            if local_date_from_git_iso8601(head_committer_iso) != today:
                continue

        selected.append(
            RepoInfo(
                path=repo_dir,
                head_commit=head_commit,
                head_committer_iso=head_committer_iso,
            )
        )

    return selected
